/**
 * Image Component
 *
 * Versatile image component supporting:
 * - An address given as `src`, `url` or `value`
 * - CSS filters
 * - Responsive sizing
 *
 * @module @uniweb/kit/Image
 */

import React, { useState, useCallback } from "react";
import { Link } from "../Link/index.js";
import { cn } from "../../utils/index.js";

/**
 * Size presets for images
 */
const SIZE_CLASSES = {
    xs: "w-8 h-8",
    sm: "w-12 h-12",
    md: "w-16 h-16",
    lg: "w-24 h-24",
    xl: "w-32 h-32",
    "2xl": "w-48 h-48",
    full: "w-full h-full",
};

/**
 * A filter setting as the number it must be — 0 for anything else. A value is
 * written into a CSS function, so a string there could carry more than a number
 * (`1px) url(…)`). ⛔ Until 2026-10-15 values were written as given.
 */
function filterNumber(value) {
    const n = typeof value === "string" && value.trim() !== "" ? Number(value) : value;
    return typeof n === "number" && Number.isFinite(n) ? n : 0;
}

/**
 * Build CSS filter string from filter object
 * @param {Object} filter - Filter settings, each a number
 * @returns {string} CSS filter value
 */
function buildFilterStyle(filter) {
    if (!filter || typeof filter !== "object") return undefined;

    const filters = [];
    const blur = filterNumber(filter.blur);
    const brightness = filterNumber(filter.brightness);
    const contrast = filterNumber(filter.contrast);
    const grayscale = filterNumber(filter.grayscale);
    const saturate = filterNumber(filter.saturate);
    const sepia = filterNumber(filter.sepia);

    if (blur) filters.push(`blur(${blur}px)`);
    if (brightness) filters.push(`brightness(${brightness}%)`);
    if (contrast) filters.push(`contrast(${contrast}%)`);
    if (grayscale) filters.push(`grayscale(${grayscale}%)`);
    if (saturate) filters.push(`saturate(${saturate}%)`);
    if (sepia) filters.push(`sepia(${sepia}%)`);

    return filters.length > 0 ? filters.join(" ") : undefined;
}

/**
 * Image - Versatile image component
 *
 * @param {Object} props
 * @param {string} [props.size] - Size preset: 'xs', 'sm', 'md', 'lg', 'xl', '2xl', 'full'
 * @param {string|Object} [props.value] - An address, or an object with `url`/`src` and `alt`
 * @param {string} [props.src] - Direct image URL
 * @param {string} [props.url] - Direct image URL (alias)
 * @param {string} [props.alt] - Alt text for accessibility
 * @param {string} [props.href] - Make image a clickable link
 * @param {boolean|string} [props.rounded] - true for full rounding, or custom class
 * @param {Object} [props.filter] - CSS filter settings
 * @param {string} [props.loading='lazy'] - Loading strategy
 * @param {string} [props.className] - Additional CSS classes
 * @param {boolean} [props.ariaHidden] - Hide from screen readers
 * @param {Function} [props.onError] - Error callback
 * @param {Function} [props.onLoad] - Load callback
 *
 * @example
 * // Direct URL
 * <Image src="/images/hero.jpg" alt="Hero image" />
 *
 * @example
 * // A size preset, rounded
 * <Image src="/team/ada.jpg" alt="Ada" size="lg" rounded />
 *
 * @example
 * // With filters
 * <Image src="/photo.jpg" filter={{ grayscale: 100, brightness: 110 }} />
 *
 * @example
 * // Clickable image
 * <Image src="/logo.png" href="/about" alt="Company logo" />
 */
export function Image({
    size,
    value,
    src,
    url,
    alt = "",
    caption,
    figureClassName,
    captionClassName,
    href,
    rounded,
    filter,
    loading = "lazy",
    className,
    ariaHidden,
    onError,
    onLoad,
    ...props
}) {
    const [hasError, setHasError] = useState(false);

    // Determine the image source
    let resolvedSrc = src || url || "";
    let resolvedAlt = alt;

    // Handle value as direct source
    if (!resolvedSrc && value) {
        if (typeof value === "string") {
            resolvedSrc = value;
        } else if (value.url || value.src) {
            resolvedSrc = value.url || value.src;
            resolvedAlt = value.alt || resolvedAlt;
        }
    }

    // Build classes
    const sizeClass = size && SIZE_CLASSES[size];
    const roundedClass =
        rounded === true
            ? "rounded-full"
            : typeof rounded === "string"
              ? rounded
              : "";

    const imageClasses = cn("object-cover", sizeClass, roundedClass, className);

    // Build filter style
    const filterStyle = buildFilterStyle(filter);

    // Handle error
    const handleError = useCallback(
        (e) => {
            setHasError(true);
            onError?.(e);
        },
        [onError],
    );

    // Handle load
    const handleLoad = useCallback(
        (e) => {
            onLoad?.(e);
        },
        [onLoad],
    );

    // Don't render if no source or error
    if (!resolvedSrc || hasError) {
        return null;
    }

    const imageElement = (
        <img
            src={resolvedSrc}
            alt={resolvedAlt}
            loading={loading}
            className={imageClasses}
            style={filterStyle ? { filter: filterStyle } : undefined}
            onError={handleError}
            onLoad={handleLoad}
            aria-hidden={ariaHidden}
            {...props}
        />
    );

    // Wrap in link if href provided. The link wraps the bare <img>; if a
    // caption is also set, the figure wraps the link below.
    const linked = href
        ? <Link to={href} className="inline-block">{imageElement}</Link>
        : imageElement;

    // Caption present → wrap in <figure>/<figcaption> for HTML/EPUB output.
    // Foundations that prefer their own figure styling can pass a richer
    // wrapper component instead; this is the kit-level default.
    if (caption) {
        return (
            <figure className={cn("uniweb-figure my-4", figureClassName)}>
                {linked}
                <figcaption className={cn("uniweb-figcaption text-sm text-subtle mt-2", captionClassName)}>
                    {caption}
                </figcaption>
            </figure>
        );
    }

    return linked;
}

export default Image;
